) 35%,var(--line));}.email-test-state.is-failed{border-color:color-mix(in srgb,var(--danger) 35%,var(--line))}.email-test-state.is-failed small{color:var(--danger)}.email-help{margin:0;padding:0 20px 18px}.email-template-layout{display:grid;grid-template-columns:minmax(240px,.38fr) minmax(0,1fr);gap:18px;align-items:start}.email-template-list>div{display:grid;gap:5px;padding:9px}.email-template-list>div>button{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;border:0;border-radius:11px;padding:11px;background:transparent;color:var(--ink);font:inherit;text-align:left;cursor:pointer}.email-template-list>div>button:hover,.email-template-list>div>button.is-active{background:var(--surface-muted)}.email-template-list button>span:nth-child(2){display:grid;min-width:0;gap:3px}.email-template-list strong{font-size:.68rem}.email-template-list small{overflow:hidden;color:var(--muted);font-size:.57rem;line-height:1.4;text-overflow:ellipsis;white-space:nowrap}.template-state{width:8px;height:8px;border-radius:50%;background:var(--line-strong)}.template-state.is-enabled{background:var(--success)}.email-template-editor{min-width:0}.email-template-form{display:grid;gap:16px;padding:20px 22px 0}.email-template-form textarea{min-height:210px;resize:vertical;line-height:1.6}.email-template-form .email-enable{margin:0}.email-template-form>footer{margin:0 -22px}.email-placeholder-list{display:grid;gap:9px}.email-placeholder-list>strong{color:var(--ink);font-size:.64rem}.email-placeholder-list>div{display:flex;flex-wrap:wrap;gap:7px}.email-placeholder-list button{display:grid;gap:2px;border:1px solid var(--line);border-radius:9px;padding:7px 9px;background:var(--surface-muted);color:var(--ink);font:inherit;text-align:left;cursor:pointer}.email-placeholder-list code{font-size:.59rem;font-weight:800}.email-placeholder-list span{color:var(--muted);font-size:.52rem}.email-template-utilities{display:flex;align-items:center;justify-content:space-between;ga